// Source: Zimmermann Design System 2026 (Handover tokens/colors.css).
// Brand primitive and semantic alias colour tokens.
export const colors = {
  // ---- Brand / Primitive: Greys ----
  grey: {
    black: 'black',
    900: '#191919',
    800: '#282828',
    700: '#454545',
    600: '#666',
    500: '#707070',
    300: '#969696',
    200: '#d1d1d1',
    100: '#e6e6e6',
    white: 'white',
  },
  // ---- Brand / Primitive: Ivory ----
  ivory: {
    400: '#f2e9e0',
    300: '#fbf5ef',
    200: '#f6f4f1',
    100: '#f9f8f6',
  },
  // ---- Brand / Primitive: Status ----
  coral: { 500: '#f98f8c' },
  green: { 500: '#2d5a3d' },
  orange: { 500: '#d67600' },
  red: { 500: '#9c0000' },
  // ---- Brand / Primitive: Opacity (base: grey/900 #191919) ----
  opacity: {
    50: 'rgba(25, 25, 25, 0.50)',
    40: 'rgba(25, 25, 25, 0.40)',
    30: 'rgba(25, 25, 25, 0.30)',
    15: 'rgba(25, 25, 25, 0.15)',
  },
  // ---- Alias / Semantic: Background ----
  background: {
    '01': '#f9f8f6',
    '02': '#f6f4f1',
    '03': '#fbf5ef',
    '04': '#f2e9e0',
    '05': '#191919',
    '06': '#282828',
    '07': '#ffffff',
  },
  // ---- Alias / Semantic: Text ----
  text: {
    default: '#191919',
    inverse: '#ffffff',
    // Handover contradicts itself here: tokens/colors.css says #969696 "confirmed",
    // but tokens.md and contract/zimm-contract.js say #939393 and still flag it
    // unresolved. Shipping the colors.css value; confirm with the UI designer.
    inverseGrey: '#969696',
    secondary: '#666666',
    muted: '#969696',
  },
  // ---- Alias / Semantic: Border ----
  border: {
    default: '#e6e6e6',
    secondary: '#d1d1d1',
    focus: '#191919',
    forms: '#707070',
    error: '#9c0000', // no Handover counterpart; retained for form validation use
  },
  // ---- Alias / Semantic: Status ----
  status: {
    success: '#2d5a3d',
    error: '#9c0000',
    errorBackground: '#f98f8c',
    storeClosed: '#d67600',
  },
  // ---- Alias / Semantic: Link ----
  link: {
    default: '#191919',
    hover: '#707070',
  },
  // ---- Alias / Semantic: Icon ----
  icon: {
    default: '#191919',
  },
  // ---- Alias / Semantic: Action: Primary ----
  action: {
    primary: {
      bgDefault: '#191919',
      bgHover: '#969696',
      bgPressed: '#454545',
      bgDisabled: '#d1d1d1',
      bgFocused: 'black',
      text: '#ffffff',
      textDisabled: '#969696',
    },
    secondary: {
      border: '#191919',
      bgHover: '#f9f8f6',
      text: '#191919',
      textInverse: '#ffffff',
      textDisabled: '#969696',
    },
  },
};

// Global CSS class registry — source: Zimmermann Design System 2026
// Derived from: tokens/typography.css, tokens/spacing.css, tokens/buttons.css,
// tokens/form-fields.css, common.css
// CSS property names are camelCase; var(--zimm-*) references kept as literal strings.
// Injected via Chakra theme styles.global (wired in overrides/app/theme/index.ts).
import { SystemStyleObject } from '@chakra-ui/react';
import { breakpoints, grid } from './foundation/gridSystem';

// ---- Typography classes ----

const zimmTextH1Strong: SystemStyleObject = {
  fontFamily: 'var(--zimm-font-family-heading)',
  fontWeight: 'var(--zimm-font-weight-medium)',
  fontSize: 'var(--zimm-font-size-md)',
  lineHeight: 'var(--zimm-font-lineheight-md)',
  letterSpacing: 'var(--zimm-font-letterspacing-sm)',
  textTransform: 'uppercase',
};

const zimmTextH1: SystemStyleObject = {
  fontFamily: 'var(--zimm-font-family-heading)',
  fontWeight: 'var(--zimm-font-weight-regular)',
  fontSize: 'var(--zimm-font-size-md)',
  lineHeight: 'var(--zimm-font-lineheight-md)',
  letterSpacing: 'var(--zimm-font-letterspacing-sm)',
  textTransform: 'uppercase',
};

const zimmTextH2Strong: SystemStyleObject = {
  fontFamily: 'var(--zimm-font-family-heading)',
  fontWeight: 'var(--zimm-font-weight-medium)',
  fontSize: 'var(--zimm-font-size-md)',
  lineHeight: 'var(--zimm-font-lineheight-xs)',
  letterSpacing: 'var(--zimm-font-letterspacing-sm)',
};

const zimmTextH3Strong: SystemStyleObject = {
  fontFamily: 'var(--zimm-font-family-heading)',
  fontWeight: 'var(--zimm-font-weight-medium)',
  fontSize: 'var(--zimm-font-size-xs)',
  lineHeight: 'var(--zimm-font-lineheight-2xs)',
  letterSpacing: 'var(--zimm-font-letterspacing-xs)',
  textTransform: 'uppercase',
};

const zimmTextLabel: SystemStyleObject = {
  fontFamily: 'var(--zimm-font-family-body)',
  fontWeight: 'var(--zimm-font-weight-medium)',
  fontSize: 'var(--zimm-font-size-xs)',
  lineHeight: 'var(--zimm-font-lineheight-xs)',
  letterSpacing: 'var(--zimm-font-letterspacing-sm)',
};

const zimmTextCaption: SystemStyleObject = {
  fontFamily: 'var(--zimm-font-family-body)',
  fontWeight: 'var(--zimm-font-weight-medium)',
  fontSize: 'var(--zimm-font-size-3xs)',
  lineHeight: 'var(--zimm-font-lineheight-2xs)',
  letterSpacing: 'var(--zimm-font-letterspacing-sm)',
};

const zimmTextLinkLg: SystemStyleObject = {
  fontFamily: 'var(--zimm-font-family-body)',
  fontWeight: 'var(--zimm-font-weight-medium)',
  fontSize: 'var(--zimm-font-size-2xs)',
  lineHeight: 'var(--zimm-font-lineheight-3xs)',
  letterSpacing: '-0.14px',
  textTransform: 'uppercase',
  textDecoration: 'underline',
  color: 'var(--zimm-color-link-default)',
  textDecorationColor: 'currentColor',
  transition: 'color 0.15s ease',
  _hover: {
    color: 'var(--zimm-color-link-hover)',
  },
  _focusVisible: {
    outline: 'var(--zimm-border-width-default) solid var(--zimm-color-border-focus)',
    outlineOffset: '2px',
    color: 'var(--zimm-color-link-hover)',
  },
};

const zimmTextLinkSm: SystemStyleObject = {
  fontFamily: 'var(--zimm-font-family-body)',
  fontWeight: 'var(--zimm-font-weight-medium)',
  fontSize: 'var(--zimm-font-size-3xs)',
  lineHeight: 'var(--zimm-font-lineheight-4xs)',
  letterSpacing: 'var(--zimm-font-letterspacing-xs)',
  textTransform: 'capitalize',
  textDecoration: 'underline',
};

const zimmTextBtnLg: SystemStyleObject = {
  fontFamily: 'var(--zimm-font-family-body)',
  fontWeight: 'var(--zimm-font-weight-medium)',
  fontSize: 'var(--zimm-font-size-2xs)',
  lineHeight: 'var(--zimm-font-lineheight-3xs)',
  letterSpacing: 'var(--zimm-font-letterspacing-sm)',
  textTransform: 'uppercase',
};

const zimmTextBtnSm: SystemStyleObject = {
  fontFamily: 'var(--zimm-font-family-body)',
  fontWeight: 'var(--zimm-font-weight-medium)',
  fontSize: 'var(--zimm-font-size-3xs)',
  lineHeight: 'var(--zimm-font-lineheight-2xs)',
  letterSpacing: 'var(--zimm-font-letterspacing-sm)',
  textTransform: 'uppercase',
};

const zimmTextProductName: SystemStyleObject = {
  fontFamily: 'var(--zimm-font-family-body)',
  fontWeight: 'var(--zimm-font-weight-medium)',
  fontSize: 'var(--zimm-font-size-2xs)',
  lineHeight: 'var(--zimm-font-lineheight-3xs)',
  letterSpacing: 'var(--zimm-font-letterspacing-sm)',
  textTransform: 'uppercase',
};

const zimmTextNav: SystemStyleObject = {
  fontFamily: 'var(--zimm-font-family-body)',
  fontWeight: 'var(--zimm-font-weight-medium)',
  fontSize: 'var(--zimm-font-size-3xs)',
  lineHeight: 'normal',
  letterSpacing: 'var(--zimm-font-letterspacing-sm)',
  textTransform: 'uppercase',
};

const zimmTextSerif: SystemStyleObject = {
  fontFamily: 'var(--zimm-font-family-serif)',
  fontWeight: 'var(--zimm-font-weight-regular)',
  fontStyle: 'italic',
  fontSize: 'var(--zimm-font-size-3xs)',
  lineHeight: 'var(--zimm-font-lineheight-3xs)',
  letterSpacing: 'var(--zimm-font-letterspacing-sm)',
};

const zimmTextPrice: SystemStyleObject = {
  fontFamily: 'var(--zimm-font-family-body)',
  fontWeight: 'var(--zimm-font-weight-medium)',
  fontSize: 'var(--zimm-font-size-2xs)',
  lineHeight: 'var(--zimm-font-lineheight-2xs)',
  letterSpacing: 'var(--zimm-font-letterspacing-sm)',
};

const zimmTextFooter: SystemStyleObject = {
  fontFamily: 'var(--zimm-font-family-body)',
  fontWeight: 'var(--zimm-font-weight-medium)',
  fontSize: 'var(--zimm-font-size-4xs)',
  lineHeight: 'var(--zimm-font-lineheight-4xs)',
  letterSpacing: 'var(--zimm-font-letterspacing-footer)',
  textTransform: 'uppercase',
};

const zimmTextBody1Strong: SystemStyleObject = {
  fontFamily: 'var(--zimm-font-family-body)',
  fontWeight: 'var(--zimm-font-weight-medium)',
  fontSize: 'var(--zimm-font-size-xs)',
  lineHeight: 'var(--zimm-font-lineheight-xs)',
  letterSpacing: 'var(--zimm-font-letterspacing-xs)',
};

const zimmTextBody1: SystemStyleObject = {
  fontFamily: 'var(--zimm-font-family-body)',
  fontWeight: 'var(--zimm-font-weight-regular)',
  fontSize: 'var(--zimm-font-size-xs)',
  lineHeight: 'var(--zimm-font-lineheight-xs)',
  letterSpacing: 'var(--zimm-font-letterspacing-xs)',
};

const zimmTextBody2Strong: SystemStyleObject = {
  fontFamily: 'var(--zimm-font-family-body)',
  fontWeight: 'var(--zimm-font-weight-medium)',
  fontSize: 'var(--zimm-font-size-2xs)',
  lineHeight: 'var(--zimm-font-lineheight-2xs)',
  letterSpacing: 'var(--zimm-font-letterspacing-xs)',
};

const zimmTextBody2: SystemStyleObject = {
  fontFamily: 'var(--zimm-font-family-body)',
  fontWeight: 'var(--zimm-font-weight-regular)',
  fontSize: 'var(--zimm-font-size-2xs)',
  lineHeight: 'var(--zimm-font-lineheight-2xs)',
  letterSpacing: 'var(--zimm-font-letterspacing-sm)',
};

const zimmTextMobileBody1Strong: SystemStyleObject = {
  fontFamily: 'var(--zimm-font-family-body)',
  fontWeight: 'var(--zimm-font-weight-medium)',
  fontSize: 'var(--zimm-font-size-2xs)',
  lineHeight: 'var(--zimm-font-lineheight-2xs)',
  letterSpacing: 'var(--zimm-font-letterspacing-xs)',
};

const zimmTextMobileBody1: SystemStyleObject = {
  fontFamily: 'var(--zimm-font-family-body)',
  fontWeight: 'var(--zimm-font-weight-regular)',
  fontSize: 'var(--zimm-font-size-2xs)',
  lineHeight: 'var(--zimm-font-lineheight-2xs)',
  letterSpacing: 'var(--zimm-font-letterspacing-sm)',
};

const zimmTextMobileBody2: SystemStyleObject = {
  fontFamily: 'var(--zimm-font-family-body)',
  fontWeight: 'var(--zimm-font-weight-regular)',
  fontSize: 'var(--zimm-font-size-3xs)',
  lineHeight: 'var(--zimm-font-lineheight-4xs)',
  letterSpacing: 'var(--zimm-font-letterspacing-sm)',
};

// ---- Spacing: Grid utility ----

// Column counts, gutter and breakpoints are derived from foundation/gridSystem so
// this class and theme.breakpoints cannot drift apart. The media queries are
// emitted in px to match the Handover CSS; gridSystem stores the same values as em
// for Chakra, hence the 16px-root conversion.
const PX_PER_REM = 16;
const emToPx = (em: string) => `${parseFloat(em) * PX_PER_REM}px`;

const zimmGrid: SystemStyleObject = {
  display: 'grid',
  gridTemplateColumns: `repeat(${grid.columns.base}, 1fr)`,
  columnGap: grid.columnGap,
  paddingInline: 'var(--zimm-grid-margin-mobile)',
  [`@media (min-width: ${emToPx(breakpoints.md)})`]: {
    gridTemplateColumns: `repeat(${grid.columns.md}, 1fr)`,
    paddingInline: 'var(--zimm-grid-margin-tablet)',
  },
  [`@media (min-width: ${emToPx(breakpoints.xl)})`]: {
    gridTemplateColumns: `repeat(${grid.columns.xl}, 1fr)`,
    paddingInline: 'var(--zimm-grid-margin-desktop)',
  },
};

// ---- Button classes ----

const zimmBtn: SystemStyleObject = {
  position: 'relative',
  display: 'inline-flex',
  alignItems: 'center',
  justifyContent: 'center',
  gap: 'var(--zimm-size-action-gap)',
  minWidth: '80px',
  overflow: 'clip',
  cursor: 'pointer',
  fontFamily: 'var(--zimm-font-family-body)',
  fontWeight: 'var(--zimm-font-weight-medium)',
  textTransform: 'uppercase',
  letterSpacing: 'var(--zimm-font-letterspacing-sm)',
  transition: 'background-color 0.15s ease, color 0.15s ease, border-color 0.15s ease',
};

const zimmBtnFull: SystemStyleObject = {
  display: 'flex',
  width: '100%',
};

const zimmBtnLarge: SystemStyleObject = {
  height: 'var(--zimm-size-action-height-lg)',
  padding: '0 var(--zimm-size-action-padding-h-lg)',
  fontSize: 'var(--zimm-font-size-2xs)',
  lineHeight: 'var(--zimm-font-lineheight-3xs)',
};

const zimmBtnMedium: SystemStyleObject = {
  height: 'var(--zimm-size-action-height-md)',
  padding: '0 var(--zimm-size-action-padding-h-md)',
  fontSize: 'var(--zimm-font-size-3xs)',
  lineHeight: 'var(--zimm-font-lineheight-2xs)',
};

const zimmBtnPrimary: SystemStyleObject = {
  background: 'var(--zimm-color-action-primary-bg-default)',
  color: 'var(--zimm-color-action-primary-text)',
  border: 'none',
};

const zimmBtnSecondary: SystemStyleObject = {
  background: 'transparent',
  color: 'var(--zimm-color-action-secondary-text)',
  border: 'var(--zimm-border-width-default) solid var(--zimm-color-action-secondary-border)',
};

const zimmBtnIcon: SystemStyleObject = {
  display: 'inline-flex',
  alignItems: 'center',
  justifyContent: 'center',
  background: 'none',
  border: 'none',
  padding: '8px',
  cursor: 'pointer',
  transition: 'opacity var(--zimm-motion-duration-fast) var(--zimm-motion-easing-standard)',
};

// ---- Form field classes ----
// Shared flush-border row + native-control base styles, consolidated upstream in
// tokens/form-fields.css from zimm-text-input (flush variant), zimm-select and
// zimm-search. Each component still owns its own error state and its native
// control's disabled text colour — those genuinely differ per component and were
// deliberately not unified upstream.

const zimmFormRow: SystemStyleObject = {
  display: 'flex',
  alignItems: 'center',
  gap: 'var(--zimm-scale-xs)',
  borderBottom: 'var(--zimm-border-width-default) solid var(--zimm-color-border-forms)',
  padding: 'var(--zimm-scale-2xs) 0',
  minHeight: '36px',
  transition:
    'border-color var(--zimm-motion-duration-fast) var(--zimm-motion-easing-standard), box-shadow var(--zimm-motion-duration-fast) var(--zimm-motion-easing-standard)',
  _hover: {
    borderBottomColor: 'var(--zimm-color-text-default)',
  },
  _focusWithin: {
    borderBottomColor: 'var(--zimm-color-text-default)',
    boxShadow: '0 1px 0 0 var(--zimm-color-text-default)',
  },
};

const zimmFormRowDisabled: SystemStyleObject = {
  // color-mix is Baseline 2023 (Chrome 111+, Safari 16.2+, Firefox 113+).
  borderBottomColor: 'color-mix(in srgb, var(--zimm-color-grey-300) 50%, transparent)',
  pointerEvents: 'none',
};

const zimmFormRowInverse: SystemStyleObject = {
  borderBottomColor: 'var(--zimm-color-grey-white)',
  _hover: {
    borderBottomColor: 'var(--zimm-color-grey-white)',
  },
  _focusWithin: {
    borderBottomColor: 'var(--zimm-color-grey-white)',
    boxShadow: '0 1px 0 0 var(--zimm-color-grey-white)',
  },
};

const zimmFormControl: SystemStyleObject = {
  background: 'transparent',
  border: 'none',
  outline: 'none',
  padding: 0,
  fontFamily: 'var(--zimm-font-family-body)',
  fontWeight: 'var(--zimm-font-weight-regular)',
  fontSize: 'var(--zimm-font-size-2xs)',
  lineHeight: 'var(--zimm-font-lineheight-2xs)',
  color: 'var(--zimm-color-text-default)',
  _placeholder: {
    color: 'var(--zimm-color-text-secondary)',
    opacity: 1,
  },
};

// Marker class applied to the control itself alongside .zimm-form-control (not
// inferred from an ancestor), so it works on any component that opts in.
const zimmFormControlInverse: SystemStyleObject = {
  _placeholder: {
    color: 'var(--zimm-color-grey-300)',
    opacity: 1,
  },
};

// ---- Shared focus-visible utility ----

const zimmFocusVisible: SystemStyleObject = {
  _focusVisible: {
    outline: 'var(--zimm-focus-ring)',
    outlineOffset: '2px',
  },
};

export const globalStyles = {
  // Typography
  '.zimm-text-h1-strong': zimmTextH1Strong,
  '.zimm-text-h1': zimmTextH1,
  '.zimm-text-h2-strong': zimmTextH2Strong,
  '.zimm-text-h3-strong': zimmTextH3Strong,
  '.zimm-text-label': zimmTextLabel,
  '.zimm-text-caption': zimmTextCaption,
  '.zimm-text-link-lg': zimmTextLinkLg,
  '.zimm-text-link-sm': zimmTextLinkSm,
  '.zimm-text-btn-lg': zimmTextBtnLg,
  '.zimm-text-btn-sm': zimmTextBtnSm,
  '.zimm-text-product-name': zimmTextProductName,
  '.zimm-text-nav': zimmTextNav,
  '.zimm-text-serif': zimmTextSerif,
  '.zimm-text-price': zimmTextPrice,
  '.zimm-text-footer': zimmTextFooter,
  '.zimm-text-body1-strong': zimmTextBody1Strong,
  '.zimm-text-body1': zimmTextBody1,
  '.zimm-text-body2-strong': zimmTextBody2Strong,
  '.zimm-text-body2': zimmTextBody2,
  '.zimm-text-mobile-body1-strong': zimmTextMobileBody1Strong,
  '.zimm-text-mobile-body1': zimmTextMobileBody1,
  '.zimm-text-mobile-body2': zimmTextMobileBody2,
  // Grid
  '.zimm-grid': zimmGrid,
  // Buttons
  '.zimm-btn': zimmBtn,
  '.zimm-btn-full': zimmBtnFull,
  '.zimm-btn-large': zimmBtnLarge,
  '.zimm-btn-medium': zimmBtnMedium,
  '.zimm-btn-primary': zimmBtnPrimary,
  '.zimm-btn-secondary': zimmBtnSecondary,
  '.zimm-btn-icon': zimmBtnIcon,
  // Form fields
  '.zimm-form-row': zimmFormRow,
  '.zimm-form-row-disabled': zimmFormRowDisabled,
  '.zimm-form-row-inverse': zimmFormRowInverse,
  '.zimm-form-control': zimmFormControl,
  '.zimm-form-control-inverse': zimmFormControlInverse,
  // Shared utility
  '.zimm-focus-visible': zimmFocusVisible,
};

// Futura Round: licensed, self-hosted. The 10 @font-face declarations live in
// overrides/app/components/_app-config/index.tsx; the .woff2 files in
// overrides/app/static/fonts/. (Upstream source: Handover tokens/typography.css.)
// Fallbacks mirror the prototype's font stack so Century Gothic / Gill Sans renders
// on machines where Futura Round is unavailable — much closer to the brand look than Arial.
export const FONT_REGULAR =
  "'Futura Round', 'Futura LT Pro', 'Futura', 'Century Gothic', 'Gill Sans', 'Trebuchet MS', Arial, sans-serif";
export const FONT_MEDIUM =
  "'Futura Round', 'Futura LT Pro', 'Futura', 'Century Gothic', 'Gill Sans', 'Trebuchet MS', Arial, sans-serif";

// Source Serif 4 (400 italic) is the Handover's decorative serif accent, but no
// @font-face or .woff2 ships for it yet — this stack renders Georgia today.
// Self-host it (SIL OFL, free via Google Fonts) when a component first needs it.
export const FONT_SERIF = "'Source Serif 4', 'Georgia', serif";

export const fonts = {
  heading: FONT_MEDIUM,
  body: FONT_REGULAR,
  mono: FONT_REGULAR,
};

/**
 * Zimmermann custom Chakra UI theme.
 *
 * This file composes the theme from `foundation/` (brand tokens) and
 * `components/` (per-component overrides). Add a new component override by
 * creating a file in `components/` and registering it in `components/index.ts`.
 *
 * Usage:
 *   import theme from 'overrides/app/theme'
 *   <ChakraProvider theme={theme}>…</ChakraProvider>
 *
 * Extend via extendTheme() — see Chakra UI docs:
 * https://chakra-ui.com/docs/styled-system/customize-theme
 */
import baseTheme from '@salesforce/retail-react-app/app/theme';
import { extendTheme, type ThemeOverride } from '@chakra-ui/react';
import { borderWidths, breakpoints, colors, fonts, spacing, textStyles } from './foundation';
import { components } from './components';
import { globalStyles } from './globalStyles';

// Note: --zimm-* CSS custom properties are injected onto :root via a raw
// <Global> in _app-config/index.tsx (ZimmTokensGlobal). They cannot go through
// Chakra's styles.global because Chakra's style processor strips quotes from
// font-family values like "'Futura Round', sans-serif", outputting just "sans-serif".
//
// ---------------------------------------------------------------------------
// Which foundations are registered as Chakra scales, and which are not
// ---------------------------------------------------------------------------
// Registered below: borderWidths, breakpoints, colors, fonts, space, textStyles.
//
// Deliberately NOT registered, because the Zimmermann scale and the Chakra scale
// use the same key names for different values — remapping them would silently
// restyle the base retail-react-app, which uses those names at ~199 call sites:
//
//   fontSizes    Chakra md=16px xs=12px 2xs=10px 3xs=7.2px
//                Zimmermann md=24px xs=16px 2xs=14px 3xs=12px  (4 collisions)
//   transition   Chakra duration.fast=150ms slow=300ms
//                Zimmermann fast=200ms default=300ms slow=500ms
//   sizes        Chakra sizes.lg=32rem vs iconSizes.lg=20px
//
// Set type with `textStyle` (all 22 Handover text styles are registered), never a
// raw `fontSize` token. For motion, icon and action dimensions, import the
// constants from `foundation/` directly — the pattern component overrides already
// use for FONT_MEDIUM. `theme/index.test.tsx` guards these scales against being
// remapped by a future change.
//
// The 15 numeric `--zimm-scale-NNN` aliases are duplicates of the named scale
// (400 = 16px = `m`) and exist only for the .zimm-* global classes; the named
// scale is the Chakra-facing surface.

const overrides: ThemeOverride = {
  borderWidths,
  breakpoints,
  colors,
  fonts,
  space: spacing,
  textStyles,
  components,
  styles: {
    global: globalStyles,
  },
};

const theme = extendTheme(baseTheme, overrides);

export default theme;

import { FONT_MEDIUM, FONT_REGULAR, FONT_SERIF } from './fonts';

// Named text styles — source: Zimmermann Design System 2026 (Handover tokens/typography.css)
// Token name → fontFamily / fontWeight / fontSize / lineHeight / letterSpacing / transform
export const textStyles = {
  // ---- Headings ----
  // ZIM/h1-strong (.zimm-text-h1-strong): 500 weight, uppercase
  heading1Strong: {
    fontFamily: FONT_MEDIUM,
    fontSize: '24px',
    fontWeight: '500',
    lineHeight: '32px',
    letterSpacing: '0px',
    textTransform: 'uppercase' as const,
  },
  // ZIM/h1 (.zimm-text-h1): 400 weight, uppercase
  heading1: {
    fontFamily: FONT_REGULAR,
    fontSize: '24px',
    fontWeight: '400',
    lineHeight: '32px',
    letterSpacing: '0px',
    textTransform: 'uppercase' as const,
  },
  // ZIM/h2-strong (.zimm-text-h2-strong)
  heading2: {
    fontFamily: FONT_MEDIUM,
    fontSize: '24px',
    fontWeight: '500',
    lineHeight: '24px',
    letterSpacing: '0px',
  },
  // ZIM/h3-strong (.zimm-text-h3-strong)
  heading3: {
    fontFamily: FONT_MEDIUM,
    fontSize: '16px',
    fontWeight: '500',
    lineHeight: '18px',
    letterSpacing: '-0.12px',
    textTransform: 'uppercase' as const,
  },
  // ---- Body ----
  // ZIM/body1-strong (.zimm-text-body1-strong)
  body1Strong: {
    fontFamily: FONT_MEDIUM,
    fontSize: '16px',
    fontWeight: '500',
    lineHeight: '24px',
    letterSpacing: '-0.12px',
  },
  // ZIM/body1 (.zimm-text-body1)
  body1: {
    fontFamily: FONT_REGULAR,
    fontSize: '16px',
    fontWeight: '400',
    lineHeight: '24px',
    letterSpacing: '-0.12px',
  },
  // ZIM/body2-strong (.zimm-text-body2-strong)
  body2Strong: {
    fontFamily: FONT_MEDIUM,
    fontSize: '14px',
    fontWeight: '500',
    lineHeight: '18px',
    letterSpacing: '-0.12px',
  },
  // ZIM/body2 (.zimm-text-body2)
  body2: {
    fontFamily: FONT_REGULAR,
    fontSize: '14px',
    fontWeight: '400',
    lineHeight: '18px',
    letterSpacing: '0px',
  },
  // ---- Mobile body ----
  // ZIM/Mobile/Body1-strong (.zimm-text-mobile-body1-strong)
  mobileBody1Strong: {
    fontFamily: FONT_MEDIUM,
    fontSize: '14px',
    fontWeight: '500',
    lineHeight: '18px',
    letterSpacing: '-0.12px',
  },
  // ZIM/Mobile/Body1 (.zimm-text-mobile-body1)
  mobileBody1: {
    fontFamily: FONT_REGULAR,
    fontSize: '14px',
    fontWeight: '400',
    lineHeight: '18px',
    letterSpacing: '0px',
  },
  // ZIM/Mobile/Body2 (.zimm-text-mobile-body2)
  mobileBody2: {
    fontFamily: FONT_REGULAR,
    fontSize: '12px',
    fontWeight: '400',
    lineHeight: '14px',
    letterSpacing: '0px',
  },
  // ---- Utility ----
  // ZIM/Label (.zimm-text-label)
  label: {
    fontFamily: FONT_MEDIUM,
    fontSize: '16px',
    fontWeight: '500',
    lineHeight: '24px',
    letterSpacing: '0px',
  },
  // Default/Caption (.zimm-text-caption)
  caption: {
    fontFamily: FONT_MEDIUM,
    fontSize: '12px',
    fontWeight: '500',
    lineHeight: '18px',
    letterSpacing: '0px',
  },
  // ---- Links ----
  // ZIM/Link-lg (.zimm-text-link-lg): uppercase + underline
  linkLg: {
    fontFamily: FONT_MEDIUM,
    fontSize: '14px',
    fontWeight: '500',
    lineHeight: '16px',
    letterSpacing: '-0.14px',
    textTransform: 'uppercase' as const,
    textDecoration: 'underline',
  },
  // ZIM/Link-sm (.zimm-text-link-sm): capitalize + underline
  linkSm: {
    fontFamily: FONT_MEDIUM,
    fontSize: '12px',
    fontWeight: '500',
    lineHeight: '14px',
    letterSpacing: '-0.12px',
    textTransform: 'capitalize' as const,
    textDecoration: 'underline',
  },
  // ---- Buttons ----
  // ZIM/Button-lg (.zimm-text-btn-lg)
  button: {
    fontFamily: FONT_MEDIUM,
    fontSize: '14px',
    fontWeight: '500',
    lineHeight: '16px',
    letterSpacing: '0px',
    textTransform: 'uppercase' as const,
  },
  // ZIM/Button-sm (.zimm-text-btn-sm)
  buttonSm: {
    fontFamily: FONT_MEDIUM,
    fontSize: '12px',
    fontWeight: '500',
    lineHeight: '18px',
    letterSpacing: '0px',
    textTransform: 'uppercase' as const,
  },
  // ---- Commerce ----
  // ZIM/Product-name (.zimm-text-product-name)
  productNames: {
    fontFamily: FONT_MEDIUM,
    fontSize: '14px',
    fontWeight: '500',
    lineHeight: '16px',
    letterSpacing: '0px',
    textTransform: 'uppercase' as const,
  },
  // ZIM/Price (.zimm-text-price)
  price: {
    fontFamily: FONT_MEDIUM,
    fontSize: '14px',
    fontWeight: '500',
    lineHeight: '18px',
    letterSpacing: '0px',
  },
  // ---- Navigation ----
  // ZIM/Navigation (.zimm-text-nav)
  navigation: {
    fontFamily: FONT_MEDIUM,
    fontSize: '12px',
    fontWeight: '500',
    lineHeight: 'normal',
    letterSpacing: '0px',
    textTransform: 'uppercase' as const,
  },
  // ---- Footer ----
  // ZIM/Footer (.zimm-text-footer)
  footer: {
    fontFamily: FONT_MEDIUM,
    fontSize: '10px',
    fontWeight: '500',
    lineHeight: '14px',
    letterSpacing: '0.4px',
    textTransform: 'uppercase' as const,
  },
  // ---- Serif accent (Source Serif 4, italic) ----
  // Default/Serif (.zimm-text-serif)
  serif: {
    fontFamily: FONT_SERIF,
    fontSize: '12px',
    fontWeight: '400',
    fontStyle: 'italic' as const,
    lineHeight: '16px',
    letterSpacing: '0px',
  },
};

