/**
 * Theme composition regression tests.
 *
 * The design foundations are token data, not logic, so most of them can't break
 * in an interesting way. Two things genuinely can, and neither surfaces as a
 * build or type error:
 *
 *   1. A foundation stops reaching the composed theme (a missing key in
 *      `theme/index.ts`, or `extendTheme` clobbering a base scale).
 *   2. Someone remaps a Chakra scale key onto the Zimmermann value of the same
 *      name. Four of the five design-system font sizes collide with Chakra
 *      defaults (`md`, `xs`, `2xs`, `3xs`), and the base retail-react-app uses
 *      those names at ~199 call sites — so remapping silently restyles base
 *      components. See the `scale token collisions` block below.
 */
import React from 'react';
import { describe, expect, test } from 'vitest';
import { render } from '@testing-library/react';
import { Button, ChakraProvider, Text } from '@chakra-ui/react';
import theme from './index';
import { textStyles } from './foundation/typography';
import { globalStyles } from './globalStyles';
import { actionSizes, iconSizes } from './foundation/sizes';
import { zimmTokens } from './foundation/zimmTokens';
import { colors } from './foundation/colour';
import { borderWidths, spacing } from './foundation/spacing';
import { grid } from './foundation/gridSystem';
import { motion } from './foundation/motion';

// Counts are drift detectors: both surfaces are ported 1:1 from the Handover
// design library, so a change here means a token was added or dropped.
const HANDOVER_TEXT_STYLE_COUNT = 22;
const HANDOVER_GLOBAL_CLASS_COUNT = 36;

describe('foundations reach the composed theme', () => {
  test('brand colours resolve through their semantic aliases', () => {
    expect(theme.colors.text.default).toBe('#191919');
    expect(theme.colors.text.inverse).toBe('#ffffff');
    expect(theme.colors.background['07']).toBe('#ffffff');
    expect(theme.colors.action.primary.bgPressed).toBe('#454545');
    expect(theme.colors.ivory[400]).toBe('#f2e9e0');
  });

  test('extendTheme merges rather than replaces the base colour scales', () => {
    // Regression guard: passing `colors` as a replacement instead of an override
    // would strip the base palette every base component still depends on.
    expect(theme.colors.gray).toBeTruthy();
    expect(theme.colors.blue).toBeTruthy();
  });

  test('body and heading fonts resolve to Futura Round with the brand fallbacks', () => {
    expect(theme.fonts.body).toContain('Futura Round');
    expect(theme.fonts.heading).toContain('Futura Round');
    // Deliberate divergence from the Handover's bare "'Futura Round', sans-serif":
    // Century Gothic / Gill Sans render far closer to the brand than Arial.
    expect(theme.fonts.body).toContain('Century Gothic');
  });

  test('space carries the named Zimmermann scale and keeps Chakra numerics', () => {
    expect(theme.space.xl).toBe('24px');
    expect(theme.space['3xs']).toBe('2px');
    expect(theme.space['7xl']).toBe('160px');
    expect(theme.space[4]).toBeTruthy();
  });

  test('borderWidths and breakpoints are wired', () => {
    expect(theme.borderWidths.default).toBe('1px');
    expect(theme.breakpoints.md).toBe('48em');
    expect(theme.breakpoints.xl).toBe('80em');
  });

  test('all Handover text styles are registered', () => {
    expect(Object.keys(textStyles)).toHaveLength(HANDOVER_TEXT_STYLE_COUNT);
    expect(Object.keys(theme.textStyles)).toHaveLength(HANDOVER_TEXT_STYLE_COUNT);
    expect(theme.textStyles.heading1.fontSize).toBe('24px');
    expect(theme.textStyles.navigation.textTransform).toBe('uppercase');
  });

  test('all .zimm-* global classes reach styles.global', () => {
    const global = theme.styles.global as Record<string, unknown>;
    const zimmClasses = Object.keys(global).filter((key) => key.startsWith('.zimm-'));
    expect(zimmClasses).toHaveLength(HANDOVER_GLOBAL_CLASS_COUNT);
    expect(Object.keys(globalStyles)).toHaveLength(HANDOVER_GLOBAL_CLASS_COUNT);
  });

  test('form-field classes are registered for the shared flush-border row', () => {
    // Ported from the Handover's tokens/form-fields.css; consumed by the text
    // input, select and search components.
    const global = theme.styles.global as Record<string, unknown>;
    expect(global['.zimm-form-row']).toBeTruthy();
    expect(global['.zimm-form-row-disabled']).toBeTruthy();
    expect(global['.zimm-form-row-inverse']).toBeTruthy();
    expect(global['.zimm-form-control']).toBeTruthy();
    expect(global['.zimm-form-control-inverse']).toBeTruthy();
  });

  test('component overrides are registered', () => {
    // ListMenu in particular: the base component reads
    // theme.components.ListMenu.baseStyle directly, so a missing entry throws
    // at render rather than falling back.
    expect(theme.components.Button).toBeTruthy();
    expect(theme.components.Header).toBeTruthy();
    expect(theme.components.ListMenu).toBeTruthy();
  });
});

describe('scale token collisions — Chakra keeps its own meanings', () => {
  test('fontSizes are NOT remapped to the Zimmermann scale', () => {
    // Design system: md 24px, xs 16px, 2xs 14px, 3xs 12px, 4xs 10px.
    // Chakra: md 16px, xs 12px, 2xs 10px, 3xs 7.2px — four collisions.
    // Type is set via `textStyle`, never a raw `fontSize` token, precisely so
    // these two scales never have to agree. If this test fails, someone has
    // remapped the scale and every base-component `fontSize` shifted with it.
    expect(theme.fontSizes.md).toBe('1rem');
    expect(theme.fontSizes.xs).toBe('0.75rem');
    expect(theme.fontSizes['2xs']).toBe('0.625rem');
  });

  test('transition durations are NOT remapped to the Zimmermann motion scale', () => {
    // Zimmermann motion: fast 200ms, default 300ms, slow 500ms.
    // Chakra: fast 150ms, slow 300ms. Component overrides import the `motion`
    // constants directly instead, the same way they import FONT_MEDIUM.
    expect(theme.transition.duration.fast).toBe('150ms');
    expect(theme.transition.duration.slow).toBe('300ms');
  });

  test('sizes are NOT remapped to the Zimmermann icon or action scales', () => {
    // theme.sizes.lg is Chakra's 32rem and backs w/h/boxSize across the base app.
    expect(theme.sizes.lg).toBe('32rem');
    // The brand dimensions live as importable constants instead.
    expect(iconSizes.lg).toBe('20px');
    expect(actionSizes.height.lg).toBe('52px');
  });
});

/**
 * The design system is expressed twice: as Chakra values (`textStyles`) and as
 * CSS custom properties behind global classes (`.zimm-text-*`). Both are ported
 * from the same Handover source, so they must agree — but nothing structurally
 * forces that, and a one-sided edit would silently split them.
 *
 * Each pair below maps a `textStyle` key to its `.zimm-text-*` class. The class
 * side stores `var(--zimm-…)` references, so values are resolved through
 * `zimmTokens` before comparison.
 */
const TEXT_STYLE_TO_CLASS: ReadonlyArray<readonly [keyof typeof textStyles, string]> = [
  ['heading1Strong', '.zimm-text-h1-strong'],
  ['heading1', '.zimm-text-h1'],
  ['heading2', '.zimm-text-h2-strong'],
  ['heading3', '.zimm-text-h3-strong'],
  ['body1Strong', '.zimm-text-body1-strong'],
  ['body1', '.zimm-text-body1'],
  ['body2Strong', '.zimm-text-body2-strong'],
  ['body2', '.zimm-text-body2'],
  ['mobileBody1Strong', '.zimm-text-mobile-body1-strong'],
  ['mobileBody1', '.zimm-text-mobile-body1'],
  ['mobileBody2', '.zimm-text-mobile-body2'],
  ['label', '.zimm-text-label'],
  ['caption', '.zimm-text-caption'],
  ['linkLg', '.zimm-text-link-lg'],
  ['linkSm', '.zimm-text-link-sm'],
  ['button', '.zimm-text-btn-lg'],
  ['buttonSm', '.zimm-text-btn-sm'],
  ['productNames', '.zimm-text-product-name'],
  ['price', '.zimm-text-price'],
  ['navigation', '.zimm-text-nav'],
  ['footer', '.zimm-text-footer'],
  ['serif', '.zimm-text-serif'],
];

/** Resolves a single `var(--zimm-…)` reference to its literal token value. */
function resolveToken(value: string | undefined): string | undefined {
  const match = value?.match(/^var\((--zimm-[a-z0-9-]+)\)$/);
  return match ? zimmTokens[match[1]] : value;
}

describe('the Chakra and CSS-variable surfaces agree', () => {
  test('every textStyle has a matching .zimm-text-* class', () => {
    expect(TEXT_STYLE_TO_CLASS).toHaveLength(HANDOVER_TEXT_STYLE_COUNT);

    const mappedStyles = TEXT_STYLE_TO_CLASS.map(([styleName]) => styleName).sort();
    expect(Object.keys(textStyles).sort()).toEqual(mappedStyles);
  });

  test.each(TEXT_STYLE_TO_CLASS)('%s matches %s', (styleName, className) => {
    const style = textStyles[styleName] as Record<string, string | undefined>;
    const globalClass = (globalStyles as Record<string, Record<string, string | undefined>>)[className];

    expect(globalClass).toBeTruthy();

    // Compared per-property rather than wholesale: the class side carries extra
    // presentational declarations (colour, hover, focus) that the textStyle
    // deliberately does not.
    for (const property of ['fontSize', 'lineHeight', 'letterSpacing', 'fontWeight', 'textTransform'] as const) {
      if (style[property] === undefined && globalClass[property] === undefined) continue;
      expect(resolveToken(globalClass[property])).toBe(style[property]);
    }
  });
});

/**
 * Every foundation value is written down twice: once as a TypeScript constant for
 * Chakra, once as a `--zimm-*` custom property for the global classes. Nothing
 * structurally forces the two to agree, so each pair is checked here.
 *
 * Notation is normalised before comparison — the CSS-variable side mirrors the
 * Handover source verbatim, which uses `white` and `#666` where the TypeScript
 * side spells the same colours `#ffffff` and `#666666`. Those are the same colour,
 * so they are treated as equal rather than churning a Handover-faithful file for
 * cosmetics.
 */
const CSS_COLOUR_KEYWORDS: Record<string, string> = { white: '#ffffff', black: '#000000' };

function normaliseValue(value: string): string {
  const trimmed = value.trim().toLowerCase().replace(/\s+/g, ' ');
  const keyword = CSS_COLOUR_KEYWORDS[trimmed];
  if (keyword) return keyword;

  const shorthand = trimmed.match(/^#([0-9a-f])([0-9a-f])([0-9a-f])$/);
  if (shorthand) {
    const [, r, g, b] = shorthand;
    return `#${r}${r}${g}${g}${b}${b}`;
  }

  return trimmed === '0' ? '0px' : trimmed;
}

const kebab = (value: string) => value.replace(/([A-Z])/g, '-$1').toLowerCase();

// Token paths whose CSS-variable name doesn't follow the mechanical
// `group.camelCase` -> `group-kebab-case` rule.
const COLOUR_NAME_OVERRIDES: Record<string, string> = {
  'background.01': 'bg-01',
  'background.02': 'bg-02',
  'background.03': 'bg-03',
  'background.04': 'bg-04',
  'background.05': 'bg-05',
  'background.06': 'bg-06',
  'background.07': 'bg-07',
  'status.errorBackground': 'status-error-bg',
};

// border.error has no Handover counterpart — it was added for form validation and
// is flagged as open with the UI designer, so it has no CSS-variable twin to match.
const COLOURS_WITHOUT_CSS_VAR = new Set(['border.error']);

function flattenColours(node: unknown, path: string): Array<[string, string]> {
  if (typeof node === 'string') return [[path, node]];
  if (node !== null && typeof node === 'object') {
    return Object.entries(node as Record<string, unknown>).flatMap(([key, value]) =>
      flattenColours(value, path ? `${path}.${key}` : key),
    );
  }
  return [];
}

describe('every foundation constant matches its --zimm-* twin', () => {
  const colourPairs = flattenColours(colors, '').filter(([path]) => !COLOURS_WITHOUT_CSS_VAR.has(path));

  test('the colour palette is fully mapped', () => {
    // Guards the exclusion list: if a colour is added without a CSS-variable twin,
    // this count drifts and the per-token test below reports the missing name.
    expect(colourPairs.length).toBeGreaterThan(0);
    expect(COLOURS_WITHOUT_CSS_VAR.size).toBe(1);
  });

  test.each(colourPairs)('colors.%s', (path, tsValue) => {
    const suffix = COLOUR_NAME_OVERRIDES[path] ?? kebab(path).replace(/\./g, '-');
    const varName = `--zimm-color-${suffix}`;

    expect(zimmTokens[varName], `${varName} is missing from zimmTokens`).toBeDefined();
    expect(normaliseValue(zimmTokens[varName])).toBe(normaliseValue(tsValue));
  });

  // Non-colour foundations. Listed explicitly rather than derived: the naming rules
  // differ per category (scale/size/motion/grid prefixes), so a table is clearer
  // than four separate transforms.
  const dimensionPairs: ReadonlyArray<readonly [string, string, string]> = [
    ...Object.entries(spacing).map(([key, value]) => [`spacing.${key}`, value, `--zimm-scale-${key}`] as const),
    ['borderWidths.default', borderWidths.default, '--zimm-border-width-default'],
    ...Object.entries(iconSizes).map(([key, value]) => [`iconSizes.${key}`, value, `--zimm-icon-size-${key}`] as const),
    ['actionSizes.height.lg', actionSizes.height.lg, '--zimm-size-action-height-lg'],
    ['actionSizes.height.md', actionSizes.height.md, '--zimm-size-action-height-md'],
    ['actionSizes.paddingX.lg', actionSizes.paddingX.lg, '--zimm-size-action-padding-h-lg'],
    ['actionSizes.paddingX.md', actionSizes.paddingX.md, '--zimm-size-action-padding-h-md'],
    ['actionSizes.gap', actionSizes.gap, '--zimm-size-action-gap'],
    ['grid.containerPadding.base', grid.containerPadding.base, '--zimm-grid-margin-mobile'],
    ['grid.containerPadding.md', grid.containerPadding.md, '--zimm-grid-margin-tablet'],
    ['grid.containerPadding.xl', grid.containerPadding.xl, '--zimm-grid-margin-desktop'],
    ['motion.duration.fast', motion.duration.fast, '--zimm-motion-duration-fast'],
    ['motion.duration.default', motion.duration.default, '--zimm-motion-duration-default'],
    ['motion.duration.slow', motion.duration.slow, '--zimm-motion-duration-slow'],
    ['motion.easing.standard', motion.easing.standard, '--zimm-motion-easing-standard'],
    ['motion.easing.slides', motion.easing.slides, '--zimm-motion-easing-slides'],
    ['motion.easing.fades', motion.easing.fades, '--zimm-motion-easing-fades'],
  ];

  test.each(dimensionPairs)('%s', (_label, tsValue, varName) => {
    expect(zimmTokens[varName], `${varName} is missing from zimmTokens`).toBeDefined();
    expect(normaliseValue(zimmTokens[varName])).toBe(normaliseValue(tsValue));
  });

  test('the font families are a single shared definition, not a copy', () => {
    // zimmTokens imports these from ./fonts, so they cannot drift by construction.
    expect(zimmTokens['--zimm-font-family-body']).toBe(theme.fonts.body);
    expect(zimmTokens['--zimm-font-family-heading']).toBe(theme.fonts.heading);
  });
});

describe('rendered output', () => {
  test('textStyle applies the brand type style end to end', () => {
    const { getByTestId } = render(
      <ChakraProvider theme={theme}>
        <Text data-testid="body-1" textStyle="body1">
          Zimmermann
        </Text>
      </ChakraProvider>,
    );

    const styles = window.getComputedStyle(getByTestId('body-1'));
    expect(styles.fontSize).toBe('16px');
    expect(styles.lineHeight).toBe('24px');
  });

  test('Button renders square and uppercase from the theme override', () => {
    const { getByRole } = render(
      <ChakraProvider theme={theme}>
        <Button>Add to bag</Button>
      </ChakraProvider>,
    );

    const styles = window.getComputedStyle(getByRole('button'));
    expect(styles.textTransform).toBe('uppercase');
    expect(styles.borderRadius).toBe('0px');
  });
});

