import React from 'react';
import type { Meta, StoryObj } from '@storybook/react-webpack5';
import { Divider, Stack, Text } from '@chakra-ui/react';
import { textStyles } from '../../theme/foundation/typography';

/**
 * Renders every registered text style through the `textStyle` prop — the only
 * sanctioned way to set type in this codebase. Four of the five design-system
 * font sizes collide with Chakra's own `fontSizes` keys (`md`, `xs`, `2xs`,
 * `3xs`), so raw `fontSize` tokens are deliberately not used; see
 * `theme/index.test.tsx` for the guard that keeps those two scales apart.
 *
 * This story doubles as the visual check that Futura Round actually loaded — if
 * the specimens render in Century Gothic or a generic sans, the @font-face rules
 * in `_app-config` are not reaching Storybook.
 */
