// Futura Round: licensed, self-hosted. The 10 @font-face declarations live in
// overrides/app/components/_app-config/index.tsx; the .woff2 files in
// overrides/app/static/fonts/. (Upstream source: Handover tokens/typography.css.)
// Fallbacks mirror the prototype's font stack so Century Gothic / Gill Sans renders
// on machines where Futura Round is unavailable — much closer to the brand look than Arial.
export const FONT_REGULAR =
  "'Futura Round', 'Futura LT Pro', 'Futura', 'Century Gothic', 'Gill Sans', 'Trebuchet MS', Arial, sans-serif";
export const FONT_MEDIUM =
  "'Futura Round', 'Futura LT Pro', 'Futura', 'Century Gothic', 'Gill Sans', 'Trebuchet MS', Arial, sans-serif";

// Source Serif 4 (400 italic) is the Handover's decorative serif accent, but no
// @font-face or .woff2 ships for it yet — this stack renders Georgia today.
// Self-host it (SIL OFL, free via Google Fonts) when a component first needs it.
export const FONT_SERIF = "'Source Serif 4', 'Georgia', serif";

export const fonts = {
  heading: FONT_MEDIUM,
  body: FONT_REGULAR,
  mono: FONT_REGULAR,
};

import React from 'react';
import type { Meta, StoryObj } from '@storybook/react-webpack5';
import { Divider, Stack, Text } from '@chakra-ui/react';
import { textStyles } from '../../theme/foundation/typography';

/**
 * Renders every registered text style through the `textStyle` prop — the only
 * sanctioned way to set type in this codebase. Four of the five design-system
 * font sizes collide with Chakra's own `fontSizes` keys (`md`, `xs`, `2xs`,
 * `3xs`), so raw `fontSize` tokens are deliberately not used; see
 * `theme/index.test.tsx` for the guard that keeps those two scales apart.
 *
 * This story doubles as the visual check that Futura Round actually loaded — if
 * the specimens render in Century Gothic or a generic sans, the @font-face rules
 * in `_app-config` are not reaching Storybook.
 */
const SPECIMEN = 'Zimmermann';

type TextStyleName = keyof typeof textStyles;

function Specimen({ name }: { name: TextStyleName }) {
  const style = textStyles[name] as Record<string, string | undefined>;
  const tracking = style.letterSpacing && style.letterSpacing !== '0px' ? ` / ${style.letterSpacing}` : '';

  return (
    <Stack spacing={2}>
      <Text textStyle="mobileBody2" color="text.secondary">
        {name} — {style.fontSize} / {style.lineHeight}
        {tracking}
      </Text>
      <Text textStyle={name}>{SPECIMEN}</Text>
    </Stack>
  );
}

function TypeScale() {
  const names = Object.keys(textStyles) as TextStyleName[];

  return (
    <Stack spacing={6} divider={<Divider borderColor="border.default" />}>
      {names.map((name) => (
        <Specimen key={name} name={name} />
      ))}
    </Stack>
  );
}

const meta: Meta<typeof TypeScale> = {
  title: 'Foundation/Typography',
  parameters: {
    layout: 'padded',
  },
};

export default meta;

type Story = StoryObj<typeof TypeScale>;

export const Default: Story = {
  render: () => <TypeScale />,
};

