input.command:
node -e '
const L=h=>{h=h.replace("#","");if(h.length===3)h=h.split("").map(c=>c+c).join("");
const v=[0,2,4].map(i=>parseInt(h.substr(i,2),16)/255).map(c=>c<=0.04045?c/12.92:Math.pow((c+0.055)/1.055,2.4));
return 0.2126*v[0]+0.7152*v[1]+0.0722*v[2];};
const C=(a,b)=>{const l1=L(a),l2=L(b);const[hi,lo]=l1>l2?[l1,l2]:[l2,l1];return (hi+0.05)/(lo+0.05);};
console.log("CHAKRA BUTTON focus indicator = background change only (outline:none)");
console.log("");
console.log("  primary   default bg #191919 -> focused bg #000000 :", C("#191919","#000000").toFixed(2)+":1", "  (needs 3:1)  FAIL");
console.log("  secondary default bg #ffffff -> focused bg #000000 :", C("#ffffff","#000000").toFixed(2)+":1", " PASS");
console.log("");
console.log("HARDCODED RING #191919 on dark surfaces");
console.log("  on bg-05 #191919 :", C("#191919","#191919").toFixed(2)+":1  FAIL");
console.log("  on bg-06 #282828 :", C("#191919","#282828").toFixed(2)+":1  FAIL");
console.log("  handover inverse ring #ffffff on bg-05 :", C("#ffffff","#191919").toFixed(2)+":1  PASS");
'

