--- a/overrides/app/theme/components/button.ts
+++ b/overrides/app/theme/components/button.ts
@@ -13,8 +13,13 @@ const baseStyle = {
   // 0.15s matches no motion token (fast 200ms / default 300ms) — left as-is
   // pending the UI designer's confirmation rather than retimed silently.
   transition: 'background-color 0.15s ease, border-color 0.15s ease, color 0.15s ease',
+  // Outline ring, per the Handover (tokens/buttons.css) and the component contract's a11y
+  // field ("Focus ring via outline (offset 2px primary, 3px secondary)"). Chakra's default
+  // ring is suppressed via boxShadow, not by dropping the outline — a background-only
+  // focus state is invisible on the primary variant, whose resting bg is already #191919.
   _focusVisible: {
-    outline: 'none',
+    outline: 'var(--zimm-focus-ring)',
+    outlineOffset: '2px',
     boxShadow: 'none',
   },
 };
@@ -41,10 +46,14 @@ const variants = {
       opacity: 1,
       cursor: 'not-allowed',
     },
+    // The bg/border shift to black is the prototype's focus treatment and is kept, but it
+    // is not the indicator — #191919 to #000000 is 1.19:1, well under the 3:1 that
+    // WCAG 1.4.11 requires. The inherited outline ring does the work.
     _focusVisible: {
       bg: 'grey.black',
       borderColor: 'grey.black',
-      outline: 'none',
+      outline: 'var(--zimm-focus-ring)',
+      outlineOffset: '2px',
       boxShadow: 'none',
     },
   },
@@ -70,11 +79,13 @@ const variants = {
       opacity: 1,
       cursor: 'not-allowed',
     },
+    // 3px offset, per the Handover: it has to clear this variant's own 1px border.
     _focusVisible: {
       bg: 'grey.black',
       borderColor: 'grey.black',
       color: 'text.inverse',
-      outline: 'none',
+      outline: 'var(--zimm-focus-ring)',
+      outlineOffset: '3px',
       boxShadow: 'none',
     },
   },

